const XLSX = require('xlsx');
const { createClient } = require('@supabase/supabase-js');

// ==========================================
// 1. CONFIGURAÇÕES DO SUPABASE
// ==========================================
const SUPABASE_URL = 'https://jydebhtmfzfpudgsvwka.supabase.co';
const SUPABASE_SERVICE_KEY = 'sb_publishable_5wbjgQTWi_U7jKmJhKI57w_VdXuYoeE'; 
const _supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY);

// Caminhos dos arquivos na mesma pasta
const CAMINHO_BRUTA = './planilha_bruta.xls';
const CAMINHO_MOTORISTA = './frete_motorista.xls';

// Função auxiliar para buscar o valor testando vários nomes possíveis de coluna
function obterValor(linha, chavesPossiveis, valorPadrao = null) {
    for (const chave of chavesPossiveis) {
        if (linha[chave] !== undefined && linha[chave] !== null && String(linha[chave]).trim() !== '') {
            return linha[chave];
        }
    }
    return valorPadrao;
}

// Limpeza de valores monetários
function limparMoeda(valor) {
    if (valor === null || valor === undefined) return 0.0;
    if (typeof valor === 'number') return valor;
    let strValor = String(valor).replace(/R\$/g, '').replace(/\./g, '').replace(/,/g, '.').trim();
    return parseFloat(strValor) || 0.0;
}

// Formatação de datas para o padrão YYYY-MM-DD
function formatarData(valorData) {
    if (!valorData) return null;
    
    if (typeof valorData === 'string') {
        const partes = valorData.trim().split('/');
        if (partes.length === 3) {
            return `${partes[2]}-${partes[1].padStart(2, '0')}-${partes[0].padStart(2, '0')}`;
        }
    } else if (typeof valorData === 'number') {
        const dataObj = XLSX.SSF.parse_date_code(valorData);
        if (dataObj) {
            return `${dataObj.y}-${String(dataObj.m).padStart(2, '0')}-${String(dataObj.d).padStart(2, '0')}`;
        }
    }
    return null;
}

async function processarEEnviarDados() {
    console.log("📖 Lendo as duas planilhas...");

    try {
        // 1. Lê a planilha bruta (onde está o Tipo de CT-e / Tipo Movimento)
        const wbBruta = XLSX.readFile(CAMINHO_BRUTA);
        const dadosBrutos = XLSX.utils.sheet_to_json(wbBruta.Sheets[wbBruta.SheetNames[0]]);
        console.log(`📊 Planilha Bruta: ${dadosBrutos.length} linhas encontradas.`);

        // Cria um mapa indexado pelo número do manifesto para busca rápida
        const mapaTipoCte = {};
        dadosBrutos.forEach(b => {
            const numManifesto = String(b['Número Manifesto'] || '').trim();
            const tipoMovimento = b['Tipo Movimento'] || b['Tipo Serviço'] || 'EMBARQUE';
            if (numManifesto) {
                mapaTipoCte[numManifesto] = tipoMovimento;
            }
        });

        // 2. Lê a planilha de frete do motorista (onde estão os valores e agregados)
        const wbMotorista = XLSX.readFile(CAMINHO_MOTORISTA);
        const dadosMotorista = XLSX.utils.sheet_to_json(wbMotorista.Sheets[wbMotorista.SheetNames[0]]);
        console.log(`📊 Planilha Frete Motorista: ${dadosMotorista.length} linhas encontradas.`);

        const dadosLimpos = [];

        for (const linha of dadosMotorista) {
            const motorista = obterValor(linha, ['Motorista', 'MOTORISTA', 'motorista']);
            if (!motorista) continue;

            const nomeMotoristaStr = String(motorista).trim().toUpperCase();

            // Filtro de Agregados (Valor Agregado Bruto > 0)
            const valorAgregadoBrutoRaw = obterValor(linha, ['Valor Agregado Bruto', 'valor_agregado_bruto'], 0.0);
            const freteMotorista = limparMoeda(valorAgregadoBrutoRaw);

            if (freteMotorista <= 0) {
                continue; // Pula frota própria
            }

            // Chave de cruzamento (Número da linha na motorista corresponde ao Número Manifesto na bruta)
            const numManifestoStr = String(obterValor(linha, ['Número', 'Contrato', 'Pré Manifesto'], '')).trim();
            const tipoCte = mapaTipoCte[numManifestoStr] || 'EMBARQUE';

            const rawData = obterValor(linha, ['Data', 'Emissão CT-e', 'Coleta', 'Data Fechamento']);
            const cte = obterValor(linha, ['Contrato', 'Número', 'CTE'], '');
            const placa = obterValor(linha, ['Veículo', 'Placa Veículo', 'Placa'], '');
            
            // Frete Cebrace obtido exclusivamente de 'Total Frete'
            const freteCebraceRaw = obterValor(linha, ['Total Frete', 'total_frete'], 0.0);

            // Regra de enlonamento: Fixo 118,44, exceto Julio Edson Cavinatti (0)
            let enlonamento = 118.44;
            if (nomeMotoristaStr.includes('JULIO EDSON CAVINATTI') || nomeMotoristaStr.includes('JULIO EDSON CAVINATI')) {
                enlonamento = 0.0;
            }

            dadosLimpos.push({
                data_registro: formatarData(rawData),
                motorista: nomeMotoristaStr,
                tipo_cte: String(tipoCte).trim(),
                cte: String(cte).trim(),
                placa: String(placa).trim().toUpperCase(),
                frete_cebrace: limparMoeda(freteCebraceRaw),
                enlonamento: enlonamento,
                frete_motorista: freteMotorista
            });
        }

        console.log(`🧹 ${dadosLimpos.length} registros cruzados, filtrados e formatados com sucesso!`);

        // 3. Limpa a tabela antiga no Supabase e insere os novos dados consolidados
        console.log("🗑️ Limpando dados antigos da tabela 'fretes' no Supabase...");
        await _supabase.from('fretes').delete().neq('id', 0);

        console.log("🚀 Enviando dados consolidados para o Supabase...");
        const { error } = await _supabase
            .from('fretes')
            .insert(dadosLimpos);

        if (error) {
            console.error("❌ Erro ao enviar para o Supabase:", error.message);
        } else {
            console.log("✅ Sucesso! Sincronização concluída cruzando Tipo de CT-e, Total Frete e Valores Agregados.");
        }

    } catch (err) {
        console.error("❌ Erro no processamento:", err.message);
    }
}

processarEEnviarDados();